mapper.select:
SELECT id, emp_id, check_date, check_in_time, check_out_time, status
FROM attendance_checkin
WHERE emp_id = #{empId}
    AND YEAR(check_date) = #{year}
  AND MONTH(check_date) = #{month}
ORDER BY check_date ASC

SELECT
    SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) normalCount,
    SUM(CASE WHEN status = 2 THEN 1 ELSE 0 END) lateCount,
    SUM(CASE WHEN status = 3 THEN 1 ELSE 0 END) missCount,
    SUM(CASE WHEN status = 4 THEN 1 ELSE 0 END) leaveCount
FROM attendance_checkin
WHERE emp_id = #{empId}
    AND YEAR(check_date) = #{year}
  AND MONTH(check_date) = #{month}
